fixtures.fixed_code:
import { expect, test } from './fixtures.js';

test('provisions an order via checkout, then reads it back', async ({ page }) => {
  await page.goto('/login');
  await page.getByTestId('login-username').fill('qa');
  await page.getByTestId('login-password').fill('qa1234');
  await page.getByTestId('login-submit').click();
  await page.waitForURL('**/products');

  await expect(page.locator('article.card').first()).toBeVisible();
  await page.getByRole('button', { name: 'Add to cart' }).first().click();
  await expect(page.locator('p.ok')).toBeVisible();

  const token = await page.evaluate(() => localStorage.getItem('demo_token'));
  const checkout = await page.request.post('/api/checkout', {
    headers: { Authorization: `Bearer ${token}` },
  });
  expect(checkout.status()).toBe(201);
  const order = await checkout.json();

  const res = await page.request.get(`/api/orders/${order.id}`, {
    headers: { Authorization: `Bearer ${token}` },
  });
  expect(res.status()).toBe(200);
  const body = await res.json();
  expect(body.id).toBe(order.id);
});

